const V='red-quiz-v3';self.addEventListener('install',e=>{e.waitUntil(caches.open(V).then(c=>c.addAll(["./","./index.html","./styles.css","./app.js","./manifest.webmanifest","./knowledge.de.json","./knowledge.en.json","./assets/icon-192.png","./assets/icon-512.png","./assets/image-1.png","./assets/image-2.png","./assets/image-3.png","./assets/image-4.png","./assets/image-5.png","./assets/image-6.png","./assets/image-7.png","./assets/image-8.png","./assets/image-9.png","./assets/image.png"])).then(()=>self.skipWaiting()).catch(()=>{}))});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==V).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{const req=e.request;if(req.method!=='GET')return;e.respondWith(fetch(req).then(r=>{if(r.ok){const z=r.clone();caches.open(V).then(c=>c.put(req,z))}return r}).catch(()=>caches.match(req).then(x=>x||(req.mode==='navigate'?caches.match('./index.html'):Response.error()))));});